const OEM_BASE='';
const TOTAL_Q=SCENARIOS.reduce((n,sc)=>n+sc.questions.length,0);
const categoryLabels={red:'ΚΟΚΚΙΝΗ · προειδοποίηση ή κατάσταση',amber:'ΚΙΤΡΙΝΗ / ΠΟΡΤΟΚΑΛΙ · προειδοποίηση / κατάσταση',green:'ΠΡΑΣΙΝΗ · λειτουργική κατάσταση',blue:'ΜΠΛΕ · πληροφορία / φωτισμός',info:'ΟΥΔΕΤΕΡΟ ΧΡΩΜΑ · κατάσταση ή μη καθορισμένο'};
const $=id=>document.getElementById(id);let filter='all',power='all',chosen='brakes-red',caseIndex=0,finished=false,submitting=false,answers={};
function esc(v){return String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));}
const lampMap=Object.fromEntries(RECORDS.map(r=>[r.id,r]));
function icon(rec,big=false){if(!rec)return '';const g=GLYPHS[rec.glyph]||GLYPHS.alert;const fallback=`<svg class="fallback-icon" viewBox="0 0 64 64" aria-hidden="true">${g}</svg>`;const manufacturer=rec.oem?`<img class="oem-icon" loading="lazy" alt="" src="${OEM_BASE+encodeURIComponent(rec.oem)}" onload="this.parentElement.classList.add('has-oem')" onerror="this.remove()">`:'';return `<span class="icon-frame ${esc(rec.category)}" role="img" aria-label="${esc(rec.name)}">${fallback}${manufacturer}</span>`;}
function renderCatalog(){const q=$('query').value.trim().toLocaleLowerCase('el');const found=RECORDS.filter(r=>(filter==='all'||r.category===filter)&&(power==='all'||r.variant==='all'||r.variant===power)&&(!q||[r.name,r.meaning,r.system,r.tech,r.ecu,r.variant].join(' ').toLocaleLowerCase('el').includes(q)));$('count').textContent=`${found.length} από ${RECORDS.length} ενδείξεις · έκδοση κινητήρα: ${power==='all'?'όλες':power}`;if(found.length&&!found.some(r=>r.id===chosen)){chosen=found[0].id;renderDetail()};$('lamp-grid').innerHTML=found.map(r=>`<button class="lamp ${r.id===chosen?'selected':''}" type="button" data-id="${esc(r.id)}" aria-pressed="${r.id===chosen}" aria-label="${esc(r.name)}">${icon(r)}<span class="name">${esc(r.name)}</span></button>`).join('')||'<div class="empty">Δεν βρέθηκαν ενδείξεις. Άλλαξε την αναζήτηση ή τα φίλτρα.</div>';$('lamp-grid').querySelectorAll('button[data-id]').forEach(b=>b.addEventListener('click',()=>{chosen=b.dataset.id;renderCatalog();renderDetail()}));}
function renderDetail(){const r=lampMap[chosen];if(!r)return;$('detail').innerHTML=`<div class="detail-top">${icon(r,true)}<div><h2>${esc(r.name)}</h2><div class="severity ${esc(r.category)}">${categoryLabels[r.category]}</div></div></div><h3>ΤΙ ΔΗΛΩΝΕΙ Η ΕΝΔΕΙΞΗ</h3><p>${esc(r.meaning)}</p><h3>ΕΝΕΡΓΕΙΑ ΟΔΗΓΟΥ / ΠΡΩΤΟΣ ΕΛΕΓΧΟΣ</h3><p>${esc(r.tech)}</p><h3>ΣΥΝΔΕΣΗ ΜΕ ECU, ΑΙΣΘΗΤΗΡΕΣ ΚΑΙ ΔΙΚΤΥΟ</h3><p>${esc(r.ecu)}</p><p class="manual-label"><b>Ενότητα:</b> ${esc(r.system)} · ${r.variant==='all'?'Όλες οι διαθέσιμες εκδόσεις':esc(r.variant)}<br>Πηγή: Mercedes-Benz C-Class Europe 2023 (M52M10_en), σ. ${esc(r.sourcePage||'86–91')}. Τα σχέδια των συμβόλων είναι εκπαιδευτικά, όχι ακριβείς αποτυπώσεις των εργοστασιακών λυχνιών. Οι τεχνικές εξηγήσεις αποτελούν εκπαιδευτικές συσχετίσεις.</p>`;}
function activateTab(which){const exp=which==='explore';$('explore').classList.toggle('hidden',!exp);$('exam').classList.toggle('hidden',exp);$('tabExplore').classList.toggle('active',exp);$('tabExam').classList.toggle('active',!exp);$('tabExplore').setAttribute('aria-selected',String(exp));$('tabExam').setAttribute('aria-selected',String(!exp));if(!exp)renderCase();}
function key(c,q){return `${c}-${q}`;}function answered(){return Object.keys(answers).length;}
function renderCase(){if(finished){renderResult();return;}const c=SCENARIOS[caseIndex];$('exam-stats').innerHTML=`<div class="stat"><b>${caseIndex+1}/${SCENARIOS.length}</b><span>Περιστατικά</span></div><div class="stat"><b>${answered()}/${TOTAL_Q}</b><span>Απαντήσεις</span></div><div class="stat"><b>${TOTAL_Q}</b><span>Τεχνικές αποφάσεις</span></div>`;$('exam-content').innerHTML=`<article class="case-card"><div class="case-head"><div><div class="eyebrow">ΕΚΠΑΙΔΕΥΤΙΚΟ ΠΕΡΙΣΤΑΤΙΚΟ ${caseIndex+1}</div><h2>${esc(c.title)}</h2></div><div class="case-icons">${c.lamps.map(id=>icon(lampMap[id])).join('')}</div></div><p class="story">${esc(c.story)}</p>${c.questions.map((q,qi)=>`<div class="question"><h3>${qi+1}. ${esc(q.question)}</h3>${q.options.map((opt,oi)=>`<label class="option"><input name="q${qi}" type="radio" value="${oi}" ${answers[key(caseIndex,qi)]===oi?'checked':''}><span>${esc(opt)}</span></label>`).join('')}</div>`).join('')}<p class="pending">Κατά την αξιολόγηση οι σωστές απαντήσεις δεν εμφανίζονται.</p><div class="actions"><button id="prev" class="action" type="button" ${caseIndex===0?'disabled':''}>← Προηγούμενο</button><button id="next" class="action primary" type="button">${caseIndex===SCENARIOS.length-1?'Ολοκλήρωση αξιολόγησης':'Επόμενο περιστατικό →'}</button></div></article>`;$('exam-content').querySelectorAll('input[type=radio]').forEach(inp=>inp.addEventListener('change',()=>{answers[key(caseIndex,Number(inp.name.slice(1)))]=Number(inp.value);$('exam-stats').children[1].querySelector('b').textContent=`${answered()}/${TOTAL_Q}`;}));$('prev').onclick=()=>{if(caseIndex>0){caseIndex--;renderCase();scrollExam()}};$('next').onclick=()=>{if(caseIndex<SCENARIOS.length-1){caseIndex++;renderCase();scrollExam()}else{openSubmit()}};}
function scrollExam(){document.querySelector('.tabs').scrollIntoView({block:'start',behavior:'smooth'})}
function openSubmit(){const miss=TOTAL_Q-answered();$('submit-text').textContent=miss?`Έχεις αφήσει ${miss} από ${TOTAL_Q} απαντήσεις κενές. Θέλεις να επιστρέψεις ή να υποβάλεις όπως είναι;`:'Έχεις απαντήσει σε όλες τις ερωτήσεις. Θέλεις να δεις αποτέλεσμα και αιτιολογήσεις;';$('submit').classList.remove('hidden');$('confirm').focus();}
function renderResult(){let score=0,empty=0;let reviews='';SCENARIOS.forEach((c,ci)=>{c.questions.forEach((q,qi)=>{const a=answers[key(ci,qi)],ok=a===q.answer;if(ok)score++;if(a===undefined)empty++;reviews+=`<section class="review"><strong class="${ok?'correct':''}">${ok?'✓ Σωστό':'✕ '+(a===undefined?'Κενή απάντηση':'Χρειάζεται επανεξέταση')} · ${esc(c.title)} · ${qi+1}</strong><p>${esc(q.question)}</p><p><b>Σωστή απάντηση:</b> ${esc(q.options[q.answer])}</p><p><b>Αιτιολόγηση:</b> ${esc(q.explanation)}</p></section>`})});$('exam-stats').innerHTML='';$('exam-content').innerHTML=`<article class="case-card"><div class="eyebrow">ΤΕΛΙΚΟ ΑΠΟΤΕΛΕΣΜΑ</div><h2>Η αξιολόγηση ολοκληρώθηκε</h2><div class="resultscore">${score} / ${TOTAL_Q}</div><p>${Math.round(score*100/TOTAL_Q)}% σωστές τεχνικές αποφάσεις${empty?' · '+empty+' κενές':''}.</p><p class="pending">Εκπαιδευτικά, υποθετικά σενάρια: δεν υποκαθιστούν διαδικασίες επισκευής και ασφαλείας.</p><button type="button" class="action primary" id="repeat">Νέα προσπάθεια</button><h2>Αναλυτική ανασκόπηση</h2>${reviews}</article>`;$('repeat').onclick=()=>{answers={};caseIndex=0;finished=false;renderCase();scrollExam()}}
$('tabExplore').onclick=()=>activateTab('explore');$('tabExam').onclick=()=>activateTab('exam');$('query').addEventListener('input',renderCatalog);$('power').addEventListener('change',e=>{power=e.target.value;renderCatalog()});document.querySelectorAll('button[data-filter]').forEach(b=>b.onclick=()=>{filter=b.dataset.filter;document.querySelectorAll('button[data-filter]').forEach(el=>{const yes=el===b;el.classList.toggle('active',yes);el.setAttribute('aria-pressed',String(yes))});renderCatalog()});$('cancel').onclick=()=>{$('submit').classList.add('hidden')};$('confirm').onclick=()=>{$('submit').classList.add('hidden');finished=true;renderResult();scrollExam()};document.addEventListener('keydown',e=>{if(e.key==='Escape')$('submit').classList.add('hidden')});renderCatalog();renderDetail();
